    ///         STABLECOIN-variant tokens. ABI-encoded and prefixed with a version byte.
    struct B20StablecoinEventParams {
        /// @dev Event-encoding version. Currently `1`. Independent of `B20StablecoinCreateParams.version`.
        uint8 version;
