+        with:
+          # Tag the triggering commit even if the branch advances while queued.
+          ref: ${{ github.sha }}
+          fetch-depth: 0
+          fetch-tags: true
+
+      - name: Create or reuse RC tag
+        env:
+          RELEASE_BRANCH: ${{ github.ref_name }}
+        run: ./scripts/release/create-tag.sh "$RELEASE_BRANCH" rc
+
+      - name: Summary
+        run: |
+          TAG=$(cat "$RUNNER_TEMP/release_tag")
+          {
+            echo "## RC tag ready"
+            echo ""
+            echo "**Tag**: \`${TAG}\`"
+          } >> "$GITHUB_STEP_SUMMARY"
