@@ -0,0 +1,41 @@
+#!/usr/bin/env bash
+
+set -euo pipefail
+
+# shellcheck source-path=SCRIPTDIR
+# shellcheck source=common.sh
+source "$(dirname "${BASH_SOURCE[0]}")/common.sh"
+
+RELEASE_BRANCH="${1:-}"
+
+if [[ -z "$RELEASE_BRANCH" ]]; then
+    echo "Usage: $0 <release_branch>" >&2
+    exit 1
+fi
+
+emit_error() {
+    local message="$1"
+    if [[ "${GITHUB_ACTIONS:-}" == true ]]; then
+        echo "::error::$message" >&2
+    else
+        echo "Error: $message" >&2
+    fi
+}
+
+main() {
+    local version
+    if ! version=$(parse_branch_version "$RELEASE_BRANCH"); then
+        emit_error "Invalid release branch: $RELEASE_BRANCH (expected releases/v<major>.<minor>.<patch>)"
+        exit 1
+    fi
+
+    local final_tag="v${version}"
+    if tag_exists "$final_tag"; then
+        emit_error "Final release tag $final_tag already exists for $RELEASE_BRANCH"
+        exit 1
+    fi
+
+    echo "No final release tag $final_tag found for $RELEASE_BRANCH."
+}
+
+main
diff --git a/scripts/release/common.sh b/scripts/release/common.sh
new file mode 100755
index 000000000..7275c7470
--- /dev/null
+++ b/scripts/release/common.sh
@@ -0,0 +1,89 @@
+#!/usr/bin/env bash
+
+set -euo pipefail
+
+parse_branch_version() {
+    local branch="$1"
+    if [[ "$branch" =~ ^releases/v([0-9]+\.[0-9]+\.[0-9]+)$ ]]; then
+        echo "${BASH_REMATCH[1]}"
+    else
+        echo "Error: Invalid branch name format: $branch" >&2
+        echo "Expected: releases/v<major>.<minor>.<patch>" >&2
+        return 1
+    fi
+}
+
+get_latest_final_version() {
+    local tag
+    while IFS= read -r tag; do
+        if [[ "$tag" =~ ^v([0-9]+\.[0-9]+\.[0-9]+)$ ]]; then
+            echo "${BASH_REMATCH[1]}"
+            return 0
+        fi
+    done < <(git tag -l 'v[0-9]*.[0-9]*.[0-9]*' --sort=-version:refname)
+    echo "Error: No final release tags found. Cannot determine current version." >&2
+    return 1
+}
+
+get_next_version() {
+    local bump_type="$1" current_version major minor patch
+    if [[ "$bump_type" != major && "$bump_type" != minor && "$bump_type" != patch ]]; then
+        echo "Error: bump_type must be 'major', 'minor', or 'patch'" >&2
+        return 1
+    fi
+    current_version=$(get_latest_final_version) || return 1
+    IFS='.' read -r major minor patch <<< "$current_version"
+    major=$((10#$major)); minor=$((10#$minor)); patch=$((10#$patch))
+    case "$bump_type" in
+        major) major=$((major + 1)); minor=0; patch=0 ;;
+        minor) minor=$((minor + 1)); patch=0 ;;
+        patch) patch=$((patch + 1)) ;;
+    esac
+    echo "${major}.${minor}.${patch}"
+}
+
+get_next_rc_number() {
+    local version="$1" tag suffix number latest_rc=0
+    while IFS= read -r tag; do
+        suffix=${tag#"v${version}"}
+        if [[ "$suffix" =~ ^(-rc\.|\.rc)([0-9]+)$ ]]; then
+            number=$((10#${BASH_REMATCH[2]}))
+            if (( number > latest_rc )); then
+                latest_rc=$number
+            fi
+        fi
+    done < <(git tag -l "v${version}-rc.*" "v${version}.rc*")
+    echo "$((latest_rc + 1))"
+}
+
+get_rc_tag() {
+    local version="$1" tag suffix rc_number
+    # Only new-format tags are reused; legacy tags still reserve their RC numbers.
+    while IFS= read -r tag; do
+        suffix=${tag#"v${version}"}
+        if [[ "$suffix" =~ ^-rc\.[0-9]+$ ]]; then
+            echo "$tag"
+            return 0
+        fi
+    done < <(git tag --list "v${version}-rc.*" --points-at HEAD --sort=-version:refname)
+    rc_number=$(get_next_rc_number "$version")
+    echo "v${version}-rc.${rc_number}"
+}
+
+tag_exists() {
+    local tag="$1"
+    git rev-parse --verify "refs/tags/$tag" >/dev/null 2>&1
+}
+
+configure_git() {
+    git config user.name "github-actions[bot]"
+    git config user.email "github-actions[bot]@users.noreply.github.com"
+}
+
+create_and_push_tag() {
+    local tag="$1"
+    local message="${2:-Release $tag}"
+
+    git tag -a "$tag" -m "$message"
+    git push origin "refs/tags/$tag"
+}
diff --git a/scripts/release/create-tag.sh b/scripts/release/create-tag.sh
new file mode 100755
index 000000000..8ae38fcd0
--- /dev/null
+++ b/scripts/release/create-tag.sh
@@ -0,0 +1,59 @@
+#!/usr/bin/env bash
+
+set -euo pipefail
+
+# shellcheck source-path=SCRIPTDIR
+# shellcheck source=common.sh
+source "$(dirname "${BASH_SOURCE[0]}")/common.sh"
+
+RELEASE_BRANCH="${1:-}"
+RELEASE_TYPE="${2:-}"
+
+if [[ -z "$RELEASE_BRANCH" || -z "$RELEASE_TYPE" ]]; then
+    echo "Usage: $0 <release_branch> <release_type> (rc|final)" >&2
+    exit 1
+fi
+
+if [[ "$RELEASE_TYPE" != rc && "$RELEASE_TYPE" != final ]]; then
+    echo "Error: release_type must be 'rc' or 'final'" >&2
+    exit 1
+fi
+
+main() {
+    echo "=== Create Release Tag ==="
+    echo "Branch: $RELEASE_BRANCH"
+    echo "Type: $RELEASE_TYPE"
+
+    VERSION=$(parse_branch_version "$RELEASE_BRANCH")
+    echo "Version: $VERSION"
+
+    local TAG TAG_SHA HEAD_SHA
+    if [[ "$RELEASE_TYPE" == rc ]]; then
+        TAG=$(get_rc_tag "$VERSION")
+        echo "Using RC tag: $TAG"
+    else
+        TAG="v${VERSION}"
+        echo "Using final release tag: $TAG"
+    fi
+
+    if tag_exists "$TAG"; then
+        TAG_SHA=$(git rev-parse "refs/tags/$TAG^{}")
+        HEAD_SHA=$(git rev-parse HEAD)
+        if [[ "$TAG_SHA" == "$HEAD_SHA" ]]; then
+            echo "Tag $TAG already exists at HEAD, skipping creation"
+        else
+            echo "Error: Tag $TAG already exists but points at $TAG_SHA, not HEAD ($HEAD_SHA)" >&2
+            exit 1
+        fi
+    else
+        configure_git
+        create_and_push_tag "$TAG"
+        echo "=== Tag $TAG created and pushed ==="
+    fi
+
+    if [[ -n "${RUNNER_TEMP:-}" ]]; then
+        echo "$TAG" > "${RUNNER_TEMP}/release_tag"
+    fi
+}
+
+main
diff --git a/scripts/release/start-release.sh b/scripts/release/start-release.sh
new file mode 100755
index 000000000..2b6bd0623
--- /dev/null
+++ b/scripts/release/start-release.sh
@@ -0,0 +1,64 @@
+#!/usr/bin/env bash
+
+set -euo pipefail
+
+# shellcheck source-path=SCRIPTDIR
+# shellcheck source=common.sh
+source "$(dirname "${BASH_SOURCE[0]}")/common.sh"
+
+BUMP_TYPE="${1:-}"
+
+if [[ -z "$BUMP_TYPE" ]]; then
+    echo "Usage: $0 <bump_type> (major|minor|patch)" >&2
+    exit 1
+fi
+
+main() {
+    echo "=== Start Release (bump: $BUMP_TYPE) ==="
+
+    CURRENT_VERSION=$(get_latest_final_version)
+    NEW_VERSION=$(get_next_version "$BUMP_TYPE")
+    RELEASE_BRANCH="releases/v${NEW_VERSION}"
+
+    local base=main major minor tag
+    if [[ "$BUMP_TYPE" == patch ]]; then
+        IFS='.' read -r major minor _ <<< "$CURRENT_VERSION"
+        base=$(git ls-remote --heads origin "releases/v${major}.${minor}.*" \
+            | awk '{print $2}' \
+            | sed -nE "s|^refs/heads/(releases/v${major}\\.${minor}\\.[0-9]+)$|\\1|p" \
+            | sort -V | tail -1)
+        if [[ -z "$base" ]]; then
+            echo "Error: No existing releases/v${major}.${minor}.* branch found on remote." >&2
+            echo "Cannot create a patch release without a prior release branch." >&2
+            exit 1
+        fi
+    fi
+
+    echo "Current version: $CURRENT_VERSION"
+    echo "New version: $NEW_VERSION"
+    echo "Release branch: $RELEASE_BRANCH"
+    echo "Base: $base"
+
+    if [[ -n "$(git ls-remote --heads origin "refs/heads/$RELEASE_BRANCH")" ]]; then
+        echo "Error: Branch $RELEASE_BRANCH already exists on remote." >&2
+        exit 1
+    fi
+
+    configure_git
+    git fetch origin "refs/heads/$base:refs/remotes/origin/$base"
+    git checkout -b "$RELEASE_BRANCH" "origin/$base"
+    tag="v${NEW_VERSION}-rc.$(get_next_rc_number "$NEW_VERSION")"
+    git tag -a "$tag" -m "Release $tag"
